mapper.select:
SELECT ca.*, co.course_name, co.credit, t.name AS teacher_name, t.teacher_no, c.class_name, c.class_code, c.college_id, cg.college_name FROM course_arrangement ca LEFT JOIN course co ON ca.course_id = co.id LEFT JOIN teacher t ON ca.teacher_id = t.id LEFT JOIN class c ON ca.class_id = c.class_code LEFT JOIN college cg ON c.college_id = cg.id
AND c.college_id = #{collegeId}
AND ca.course_id = #{courseId}
AND ca.teacher_id = #{teacherId}
AND ca.class_id = #{classId}
AND ca.semester = #{semester}
AND ca.status = #{status}
ORDER BY ca.create_time DESC

